/**
 * Stores the tenant-wide payment terms. Payment terms are a singleton setting, so this endpoint creates them on the first call (201) and overwrites them on every subsequent call (200) — there is no separate update endpoint. Any omitted field falls back to its default: payment due 15 days after completion, overdue 60 days after the due date, and reminders disabled. Note that an update replaces the record wholesale, so omitted fields are reset to their defaults rather than left untouched.
 * @summary Create or update payment terms
 */
export const savePaymentTermsBodyPaymentDueAfterDaysDefault = 15;
export const savePaymentTermsBodyPaymentDueAfterDaysMax = 365;

export const savePaymentTermsBodyMarkOverdueAfterDaysDefault = 60;
export const savePaymentTermsBodyMarkOverdueAfterDaysMax = 365;

export const savePaymentTermsBodyPaymentReminderEnabledDefault = false;
export const savePaymentTermsBodyPaymentReminderDaysMax = 365;



export const SavePaymentTermsBody = zod.object({
  "paymentDueAfterDays": zod.int().min(1).max(savePaymentTermsBodyPaymentDueAfterDaysMax).default(savePaymentTermsBodyPaymentDueAfterDaysDefault).describe('Days after work completion before payment becomes due'),
  "markOverdueAfterDays": zod.int().min(1).max(savePaymentTermsBodyMarkOverdueAfterDaysMax).default(savePaymentTermsBodyMarkOverdueAfterDaysDefault).describe('Days after the payment due date before an unpaid invoice is marked overdue'),
  "paymentReminderEnabled": zod.boolean().default(savePaymentTermsBodyPaymentReminderEnabledDefault).describe('Whether payment reminders are sent for outstanding invoices'),
  "paymentReminderDays": zod.int().min(1).max(savePaymentTermsBodyPaymentReminderDaysMax).optional().describe('Days before the due date on which a reminder is sent. Required when paymentReminderEnabled is true, ignored otherwise')
}).describe('Payment terms to store under Global Settings')

export const SavePaymentTermsResponse = zod.object({
  "id": zod.uuid().optional().describe('Identifier of the payment terms record'),
  "paymentDueAfterDays": zod.int().optional().describe('Days after work completion before payment becomes due'),
  "markOverdueAfterDays": zod.int().optional().describe('Days after the payment due date before an unpaid invoice is marked overdue'),
  "paymentReminderEnabled": zod.boolean().optional().describe('Whether payment reminders are sent for outstanding invoices'),
  "paymentReminderDays": zod.int().optional().describe('Days before the due date on which a reminder is sent. Absent when reminders are disabled'),
  "createdAt": zod.iso.datetime({"offset":true}).optional().describe('When the record was created'),
  "updatedAt": zod.iso.datetime({"offset":true}).optional().describe('When the record was last updated')
}).describe('Payment terms currently held under Global Settings')


